cat > .local/advanced-podcast/activate.mjs <<'JS'
import {execFileSync} from 'node:child_process';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {join} from 'node:path';
import {deploymentRoot,repository,readJson,writeJson} from '../../classic/scripts/local-production/common.mjs';
const candidate=await readJson(join(deploymentRoot,'candidate.json'));
const current=await readJson(join(deploymentRoot,'current.json'));
const files=execFileSync('git',['ls-files','-z','--cached','--others','--exclude-standard'],{cwd:repository,maxBuffer:64*1024**2}).toString().split('\0').filter(Boolean).sort();
const hash=createHash('sha256');
for(const file of files){
 if(file.endsWith('/next-env.d.ts'))continue;
 if(!/^(classic\/(apps\/(web|electron\/app)|rust|packages|patches)\/|crates\/|resources\/|Cargo\.(toml|lock)$|classic\/(package\.json|bun\.lock)$)/.test(file))continue;
 hash.update(file);try{hash.update(await readFile(join(repository,file)));}catch(e){if(e.code==='ENOENT')hash.update('deleted');else throw e;}
}
if(hash.digest('hex')!==candidate.fingerprint)throw Error('Candidate source differs from the tested working tree');
if((await readJson(join(deploymentRoot,'current.json'))).id!==current.id)throw Error('Production changed concurrently');
await writeJson(join(deploymentRoot,'previous.json'),current);
await writeJson(join(deploymentRoot,'current.json'),candidate);
console.log(JSON.stringify({activated:candidate.id,rollback:current.id,fingerprint:candidate.fingerprint}));
JS
node .local/advanced-podcast/activate.mjs > .local/advanced-podcast/activation.json
cat .local/advanced-podcast/activation.json
